/**
 * @summary Get barber dashboard summary
 */
export const getGetBarberDashboardUrl = (params?: GetBarberDashboardParams) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/barbers/me/dashboard?${stringifiedParams}`
    : `/api/barbers/me/dashboard`;
};

export const getBarberDashboard = async (
  params?: GetBarberDashboardParams,
  options?: RequestInit,
): Promise<BarberDashboard> => {
  return customFetch<BarberDashboard>(getGetBarberDashboardUrl(params), {
    ...options,
    method: "GET",
  });
};

export const getGetBarberDashboardQueryKey = (
  params?: GetBarberDashboardParams,
) => {
  return [`/api/barbers/me/dashboard`, ...(params ? [params] : [])] as const;
};

export const getGetBarberDashboardQueryOptions = <
  TData = Awaited<ReturnType<typeof getBarberDashboard>>,
  TError = ErrorType<unknown>,
>(
  params?: GetBarberDashboardParams,
  options?: {
    query?: UseQueryOptions<
      Awaited<ReturnType<typeof getBarberDashboard>>,
      TError,
      TData
    >;
    request?: SecondParameter<typeof customFetch>;
  },
) => {
  const { query: queryOptions, request: requestOptions } = options ?? {};

  const queryKey =
    queryOptions?.queryKey ?? getGetBarberDashboardQueryKey(params);

  const queryFn: QueryFunction<
    Awaited<ReturnType<typeof getBarberDashboard>>
  > = ({ signal }) => getBarberDashboard(params, { signal, ...requestOptions });

  return { queryKey, queryFn, ...queryOptions } as UseQueryOptions<
    Awaited<ReturnType<typeof getBarberDashboard>>,
    TError,
    TData
  > & { queryKey: QueryKey };
};

export type GetBarberDashboardQueryResult = NonNullable<
  Awaited<ReturnType<typeof getBarberDashboard>>
>;
export type GetBarberDashboardQueryError = ErrorType<unknown>;

